UPDATE USER
nickname = #{dto.nickname}, gender = #{dto.gender}, profile_image = #{dto.profileImage}, birth_date = DATE_FORMAT(#{dto.birthDate},"%Y-%m-%d"), updated_at = NOW()
WHERE user_id = #{userId}

