UPDATE USER
SET is_marketing_agreed = #{value}, updated_at = NOW()
WHERE user_id = #{userId}

INSERT INTO USER_NOTIFICATION_SETTING (user_id, type_code, is_enabled)
VALUES (#{userId}, REPLACE(#{key}, 'noti_', ''), #{value})
ON DUPLICATE KEY UPDATE is_enabled = #{value}

